pragma solidity ^0.8.22;

import "./WorldStorage.sol";
import "./Staking.sol";
import "./customDNAtoken.sol"; // Para usar la interfaz
import "./TokenFactoryDSL.sol"; // Para llamar al factory

contract MetaverseW is WorldStorage {
    TokenFactoryDSL public factory;

    event WorldCreated(
        bytes32 indexed worldId,
        string name,
        address creator,
        address tokenAddress,
        address stakingAddress
    );

    event WorldUpdated(bytes32 indexed worldId, string name);

    constructor(address _endpoint, address _owner, address _factoryAddress) WorldStorage(_endpoint, _owner) {
        factory = TokenFactoryDSL(_factoryAddress);
    }

    function createWorld(
        string memory _name,
        string memory _description,
        string memory _icon,
        string memory _symbol,
        string memory _dna //
    ) external {
        bytes32 worldId = keccak256(abi.encodePacked(_name, msg.sender));
        require(worlds[worldId].creator == address(0), "World already exists");
        require(bytes(_symbol).length > 0, "Token symbol required");

        // ✅ Crear token con ADN usando el Factory
        address tokenAddress = factory.createToken(_name, _symbol, _dna);

        // ✅ Crear contrato de staking asociado
        StakingContract newStaking = new StakingContract(tokenAddress, msg.sender);

        worlds[worldId] = World({
            name: _name,
            description: _description,
            icon: _icon,
            tokenName: _name,
            tokenSymbol: _symbol,
            dna: _dna, // ✅ aquí agregas el ADN
            creator: msg.sender,
            tokenAddress: tokenAddress,
            stakingAddress: address(newStaking),
            createdAt: block.timestamp
        });

        worldKeys.push(worldId);

        emit WorldCreated(worldId, _name, msg.sender, tokenAddress, address(newStaking));
    }

    function updateWorld(
        bytes32 _worldId,
        string memory _name,
        string memory _description,
        string memory _icon
    ) external {
        World storage world = worlds[_worldId];
        require(world.creator == msg.sender, "Not owner");

        world.name = _name;
        world.description = _description;
        world.icon = _icon;

        emit WorldUpdated(_worldId, _name);
    }

    function getWorldStaking(bytes32 worldId) external view returns (address) {
        return worlds[worldId].stakingAddress;
    }
}
