pragma solidity ^0.8.22;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract StakingContract is Ownable {
    IERC20 public stakingToken;
    mapping(address => uint256) public stakes;
    mapping(address => uint256) public stakeTimestamps; // Guarda el tiempo de stake
    uint256 public totalStaked;
    uint256 public minStakeTime = 7 days;

    event Staked(address indexed user, uint256 amount);
    event Unstaked(address indexed user, uint256 amount);

    constructor(address _token, address _owner) Ownable(_owner) {
        stakingToken = IERC20(_token);
    }

    function stake(uint256 _amount) external {
        require(stakingToken.balanceOf(msg.sender) >= _amount, "Insufficient balance");
        require(stakingToken.allowance(msg.sender, address(this)) >= _amount, "Allowance not set");

        stakingToken.transferFrom(msg.sender, address(this), _amount);
        stakes[msg.sender] += _amount;
        stakeTimestamps[msg.sender] = block.timestamp; // Guarda el tiempo de stake
        totalStaked += _amount;

        emit Staked(msg.sender, _amount);
    }

    function unstake(uint256 _amount) external {
        require(stakes[msg.sender] >= _amount, "Insufficient staked amount");
        require(block.timestamp >= stakeTimestamps[msg.sender] + minStakeTime, "Stake period not completed");

        stakes[msg.sender] -= _amount;
        totalStaked -= _amount;

        stakingToken.transfer(msg.sender, _amount);
        emit Unstaked(msg.sender, _amount);
    }

    function getStakedAmount(address _user) external view returns (uint256) {
        return stakes[_user];
    }

    function setMinStakeTime(uint256 _time) external onlyOwner {
        minStakeTime = _time;
    }
}
