pragma solidity ^0.8.19;

import "./customDNAtoken.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract TokenFactoryDSL is Ownable {
    event TokenCreated(address indexed tokenAddress, string name, string symbol, string dna);

    struct TokenInfo {
        address tokenAddress;
        string dna;
    }

    TokenInfo[] public allTokens;
    mapping(address => address[]) public tokensByCreator;

    // ✅ Constructor con owner explícito
    constructor(address initialOwner) Ownable(initialOwner) {}

    function createToken(string memory name, string memory symbol, string memory dna) external returns (address) {
        CustomDNAToken newToken = new CustomDNAToken(name, symbol, msg.sender, dna);
        allTokens.push(TokenInfo(address(newToken), dna));
        tokensByCreator[msg.sender].push(address(newToken));

        emit TokenCreated(address(newToken), name, symbol, dna);
        return address(newToken);
    }

    function getAllTokens() external view returns (TokenInfo[] memory) {
        return allTokens;
    }

    function getTokensByCreator(address creator) external view returns (address[] memory) {
        return tokensByCreator[creator];
    }
}

