pragma solidity ^0.8.22;

import "@layerzerolabs/oapp-evm/contracts/oapp/OApp.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract WorldStorage is OApp {
    struct World {
        string name;
        string description;
        string icon;
        string tokenName;
        string tokenSymbol;
        string dna;
        address creator;
        address tokenAddress;
        address stakingAddress;
        uint256 createdAt;
    }

    mapping(bytes32 => World) internal worlds;
    bytes32[] internal worldKeys;

    event WorldSynced(
        bytes32 indexed worldId,
        string name,
        address creator,
        address tokenAddress
    );

    constructor(address _endpoint, address _owner)
        OApp(_endpoint, _owner)
        Ownable(_owner)
    {}

    function getWorld(bytes32 worldId) external view returns (World memory) {
        return worlds[worldId];
    }

    function getAllWorlds() external view virtual returns (bytes32[] memory) {
    return worldKeys;
}


    function syncWorld(
        uint32 _dstEid,
        bytes32 worldId,
        bytes calldata _options
    ) external payable {
        require(worlds[worldId].creator != address(0), "World does not exist");

        bytes memory payload = abi.encode(worlds[worldId]);
        _lzSend(
            _dstEid,
            payload,
            _options,
            MessagingFee(msg.value, 0),
            payable(msg.sender)
        );

        emit WorldSynced(
            worldId,
            worlds[worldId].name,
            worlds[worldId].creator,
            worlds[worldId].tokenAddress
        );
    }

    function _lzReceive(
    Origin calldata _origin, // warning eliminado
    bytes32 _guid, // warning eliminado
    bytes calldata payload,
    address,
    bytes calldata
) internal override {
    _origin; // Evita warning
    _guid;   // Evita warning

    require(payload.length > 0, "Invalid payload");

    World memory receivedWorld = abi.decode(payload, (World));
    bytes32 worldId = keccak256(
        abi.encodePacked(receivedWorld.name, receivedWorld.creator)
    );

    if (worlds[worldId].creator == address(0)) {
        worlds[worldId] = receivedWorld;
        worldKeys.push(worldId);
        emit WorldSynced(
            worldId,
            receivedWorld.name,
            receivedWorld.creator,
            receivedWorld.tokenAddress
        );
    }
}
}","keccak256":"0x52e0383e624939c7f4618c94112f4e7ea121f0bd2c9c96d410a08848809a22dd","license":"MIT"},"contracts/customDNAtoken.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract CustomDNAToken is ERC20, Ownable {
    string private _dna; // ✅ Declaración faltante

    constructor(string memory name, string memory symbol, address creator, string memory dna)
        ERC20(name, symbol)
        Ownable(creator)
    {
        _dna = dna;
        _mint(creator, 1000 * 10 ** decimals());
    }

    function tokenDNA() external view returns (string memory) {
        return _dna;
    }
}
